(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-874":{scenario:{company:"Trường Mầm non Hoa Sen Xanh",supervisor:{name:"Trần Thị Mai Anh",role:{vi:"Phó Hiệu trưởng phụ trách bán trú",en:"Vice Principal for Day Care & Nutrition"}},ref_code:"MN-0417",title:{vi:"Bữa ăn an toàn. Hồ sơ chính xác. Minh bạch với phụ huynh.",en:"Safe meals. Accurate records. Honest with parents."},brief:{vi:"Bạn là giáo viên chủ nhiệm lớp Mẫu giáo 4-5 tuổi. Bé mã MN-0417 có giấy xác nhận của bác sĩ về dị ứng đạm sữa bò. Tháng 10 bé nghỉ 5 ngày: 3 ngày phụ huynh báo nghỉ trước 8:00, 2 ngày không báo. Tiền ăn mô phỏng 32000 đồng/ngày. Đối chiếu phiếu theo dõi nháp với hồ sơ đã duyệt, sửa mã thực đơn và số tiền ăn hoàn trả, rồi lập báo cáo có căn cứ. Đây là tình huống đào tạo.",en:"You are the homeroom teacher of a 4-5 year-old kindergarten class. Child MN-0417 has a doctor's certificate confirming cow's milk protein allergy. In October the child missed 5 days: parents notified 3 absences before 8:00 and 2 without notice. The training meal fee is 32000 VND per day. Compare the draft care record with the approved file, correct the menu code and the meal refund, then write an evidence-based report. This is a training scenario."},reference_title:{vi:"Hồ sơ sức khỏe & bảng chấm ăn đã duyệt · MN-0417",en:"Approved health file & meal attendance sheet · MN-0417"},fields:[{id:"MENU_CODE",label:{vi:"Mã thực đơn bán trú",en:"Day-care menu code"},initial:"MENU-STD",expected:"MENU-DF",choices:["MENU-STD","MENU-DF","MENU-GF"],reference:"Phiếu sức khỏe & dị ứng",hint:{vi:"Giấy bác sĩ xác nhận dị ứng đạm sữa bò: trẻ dùng thực đơn loại bỏ sữa và chế phẩm từ sữa (DF), không phải thực đơn không gluten.",en:"The doctor confirms cow's milk protein allergy: the child needs the dairy-free menu (DF), not the gluten-free one."}},{id:"REFUND_VND",label:{vi:"Tiền ăn hoàn trả tháng 10 (đồng)",en:"October meal refund (VND)"},initial:"160000",expected:"96000",reference:"Bảng chấm ăn tháng 10",ref_value:{vi:"Nghỉ 5 ngày: 3 ngày báo trước 8:00, 2 ngày không báo; tiền ăn 32000 đồng/ngày (mô phỏng)",en:"5 absences: 3 notified before 8:00, 2 without notice; meal fee 32000 VND/day (training)"},hint:{vi:"Chỉ ngày nghỉ được báo trước giờ bếp chốt suất ăn mới được hoàn tiền.",en:"Only absences notified before the kitchen's meal cut-off are refunded."}}],sop32:{vi:"Bếp chốt suất ăn lúc 8:00 hằng ngày. Chỉ hoàn tiền ăn cho ngày nghỉ được phụ huynh báo trước 8:00; tiền hoàn trả = số ngày nghỉ có báo trước x tiền ăn một ngày (số liệu mô phỏng).",en:"The kitchen closes meal orders at 8:00 daily. Only absences notified before 8:00 are refunded; refund = notified absence days x daily meal fee (training figure)."},context:{label:"SỔ THEO DÕI TRẺ / MN-0417",metrics:[{label:{vi:"Sĩ số lớp",en:"Class size"},value:"28"},{label:{vi:"Ngày nghỉ tháng 10",en:"October absences"},value:"5"},{label:{vi:"Tiền ăn mô phỏng/ngày",en:"Training meal fee/day"},value:"32,000 VND"}]},crisis:{vi:"Bếp báo hết sữa thay thế cho bé MN-0417. Một đồng nghiệp nhắn: “Cho bé uống sữa thường một bữa thôi, ít thì không sao, đừng báo phụ huynh kẻo họ làm to chuyện.”",en:"The kitchen has run out of the substitute milk for child MN-0417. A colleague texts: “Just give regular milk for one meal, a little won't hurt, and don't tell the parents or they will make a fuss.”"},options:{safe:{vi:"Không cho trẻ dùng sữa bò, yêu cầu bếp thay món an toàn theo thực đơn DF, báo Phó Hiệu trưởng, thông báo trung thực cho phụ huynh và ghi sổ theo dõi.",en:"Give no cow's milk, ask the kitchen for a safe DF substitute, inform the Vice Principal, tell the parents honestly and log it in the record."},shortcut:{vi:"Cho bé uống ít sữa thường cho đủ bữa và không ghi vào sổ theo dõi.",en:"Give a little regular milk to complete the meal and leave it out of the record."},wait:{vi:"Để bé bỏ bữa phụ, chờ bếp tự xử lý và không báo cho ai.",en:"Let the child skip the snack, wait for the kitchen to sort it out and tell no one."}},questions:{vi:["Vì sao bé MN-0417 phải dùng thực đơn MENU-DF? Căn cứ nào trong hồ sơ sức khỏe chứng minh điều đó?","Giải thích cách tính tiền ăn hoàn trả và cách bạn trao đổi với phụ huynh khi phát hiện sai lệch."],en:["Why must child MN-0417 be on MENU-DF? Which evidence in the health file supports it?","Explain how you calculated the meal refund and how you would talk to the parents about the discrepancy."]},hints:{vi:["Đặt phiếu theo dõi nháp cạnh giấy xác nhận dị ứng và đánh dấu dòng mã thực đơn đang sai.","Tách ngày nghỉ có báo trước 8:00 và ngày không báo trước khi nhân đơn giá theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi sự cố liên quan đến dị ứng phải được báo cáo và thông báo cho phụ huynh."],en:["Place the draft record next to the allergy certificate and flag the wrong menu code line.","Separate absences notified before 8:00 from unnotified ones before applying the rate in SOP 3.2.","Re-read SOP 4.2: every allergy-related incident must be reported and shared with the parents."]}},learning:{summary:{vi:"Giáo viên mầm non chăm sóc, nuôi dưỡng và giáo dục trẻ từ nhà trẻ đến mẫu giáo theo Chương trình giáo dục mầm non: tổ chức hoạt động học qua chơi, bảo đảm an toàn, dinh dưỡng, vệ sinh và theo dõi sự phát triển của từng trẻ. Nghề đòi hỏi tình yêu trẻ, hiểu biết tâm lý phát triển, kỹ năng sơ cứu, khả năng quan sát và phối hợp chặt chẽ, trung thực với gia đình.",en:"An early childhood educator cares for, nurtures and teaches children from nursery to kindergarten age under the national early childhood curriculum: organizing learning through play, ensuring safety, nutrition and hygiene, and tracking each child's development. The role requires genuine care for children, child development knowledge, first aid skills, careful observation and close, honest partnership with families."},responsibilities:{vi:["Lập kế hoạch giáo dục năm, tháng, tuần theo chủ đề và mục tiêu phát triển của độ tuổi.","Tổ chức hoạt động học qua chơi, góc chơi, hoạt động ngoài trời và chế độ sinh hoạt một ngày.","Chăm sóc bữa ăn, giấc ngủ, vệ sinh; quản lý trẻ dị ứng, bệnh mạn tính theo hồ sơ sức khỏe.","Cân đo, theo dõi biểu đồ tăng trưởng và đánh giá sự phát triển của trẻ định kỳ.","Trao đổi với phụ huynh hằng ngày, ghi sổ theo dõi và báo cáo sự cố kịp thời."],en:["Prepare yearly, monthly and weekly education plans by theme and age-group development goals.","Run learning through play, activity corners, outdoor play and the daily routine.","Manage meals, naps and hygiene; handle allergies and chronic conditions per the health file.","Weigh and measure children, track growth charts and assess development periodically.","Talk with parents daily, keep the care record and report incidents promptly."]},competencies:[{name:{vi:"Tổ chức học qua chơi",en:"Play-based learning design"},desc:{vi:"Thiết kế hoạt động phù hợp độ tuổi, lấy trẻ làm trung tâm, kích thích tò mò, ngôn ngữ và vận động.",en:"Design age-appropriate, child-centered activities that build curiosity, language and motor skills."}},{name:{vi:"Chăm sóc & an toàn",en:"Care & safety"},desc:{vi:"Phòng tránh tai nạn thương tích, sơ cứu ban đầu, quản lý dị ứng và giữ vệ sinh an toàn thực phẩm.",en:"Prevent injuries, give first aid, manage allergies and keep food hygiene safe."}},{name:{vi:"Quan sát & đánh giá phát triển",en:"Observation & developmental assessment"},desc:{vi:"Ghi chép quan sát, đối chiếu chỉ số phát triển và phát hiện sớm trẻ cần hỗ trợ can thiệp.",en:"Record observations, compare with development indicators and spot children needing early support."}},{name:{vi:"Hợp tác với gia đình",en:"Family partnership"},desc:{vi:"Trao đổi trung thực, tôn trọng, kịp thời với phụ huynh về tiến bộ và sự cố của trẻ.",en:"Communicate honestly, respectfully and promptly with parents about progress and incidents."}},{name:{vi:"Đạo đức nhà giáo",en:"Professional ethics"},desc:{vi:"Tôn trọng quyền trẻ em, không dùng hình phạt, không che giấu sự cố và bảo mật thông tin gia đình.",en:"Respect children's rights, never use punishment, never hide incidents and protect family information."}}],knowledge:{vi:["Luật Giáo dục số 43/2019/QH14 và Luật Trẻ em số 102/2016/QH13.","Chương trình giáo dục mầm non ban hành kèm Thông tư 17/2009/TT-BGDĐT, đã được sửa đổi, bổ sung (Thông tư 51/2020/TT-BGDĐT).","Điều lệ trường mầm non (Thông tư 52/2020/TT-BGDĐT): tổ chức nhóm, lớp và số trẻ tối đa theo độ tuổi.","Chuẩn nghề nghiệp giáo viên mầm non (Thông tư 26/2018/TT-BGDĐT).","Chuẩn tăng trưởng trẻ em của WHO và nguyên tắc dinh dưỡng, an toàn thực phẩm trong bếp ăn tập thể.","Sơ cứu ban đầu, phòng chống tai nạn thương tích và xử trí phản ứng dị ứng ở trẻ nhỏ."],en:["Education Law No. 43/2019/QH14 and Law on Children No. 102/2016/QH13.","The early childhood education curriculum issued with Circular 17/2009/TT-BGDDT, as amended (Circular 51/2020/TT-BGDDT).","Preschool Charter (Circular 52/2020/TT-BGDDT): group and class organization and maximum class sizes by age.","Professional standards for preschool teachers (Circular 26/2018/TT-BGDDT).","WHO child growth standards and nutrition and food safety principles for school kitchens.","First aid, injury prevention and management of allergic reactions in young children."]},tools:["Phần mềm quản lý trường mầm non","Sổ liên lạc điện tử với phụ huynh","Biểu đồ tăng trưởng chuẩn WHO","Bộ học liệu góc chơi (STEAM, Montessori)","Cân và thước đo chiều cao trẻ em","Túi sơ cứu lớp học"],kpis:{vi:["Số sự cố an toàn, dị ứng trong lớp (mục tiêu bằng 0).","Tỷ lệ trẻ được cân đo đủ kỳ và nằm trong kênh tăng trưởng bình thường.","Tỷ lệ trẻ đạt mục tiêu phát triển cuối độ tuổi.","Mức độ hài lòng của phụ huynh qua khảo sát học kỳ."],en:["Safety and allergy incidents in the class (target zero).","Share of children measured on schedule and within the normal growth channel.","Share of children meeting end-of-age development goals.","Parent satisfaction in the semester survey."]},day:[{time:"07:00",vi:"Đón trẻ, quan sát sức khỏe buổi sáng, nhận thuốc kèm phiếu gửi thuốc có chữ ký phụ huynh.",en:"Welcome children, do the morning health check and receive medicines with a signed parent request form."},{time:"08:00",vi:"Chốt sĩ số, báo suất ăn cho bếp và ghi rõ trẻ cần thực đơn đặc biệt.",en:"Confirm attendance, send meal counts to the kitchen and flag special-diet children."},{time:"09:00",vi:"Tổ chức hoạt động học theo chủ đề, chơi ở các góc và hoạt động ngoài trời.",en:"Run themed learning activities, corner play and outdoor time."},{time:"11:00",vi:"Tổ chức bữa trưa, kiểm tra lại suất ăn đặc biệt rồi cho trẻ ngủ trưa.",en:"Serve lunch, double-check special-diet meals, then supervise nap time."},{time:"16:30",vi:"Trả trẻ, trao đổi với phụ huynh và hoàn thiện sổ theo dõi trong ngày.",en:"Hand children back to parents, share updates and complete the day's care record."}],mistakes:{vi:["Không đối chiếu danh sách dị ứng khi chia suất ăn, để trẻ dị ứng ăn nhầm món.","Hoàn tiền ăn cho mọi ngày nghỉ mà không xét giờ báo nghỉ theo quy định chốt suất ăn.","Che giấu va chạm, trầy xước của trẻ thay vì ghi sổ sự cố và báo phụ huynh."],en:["Not checking the allergy list when serving meals, so an allergic child gets the wrong dish.","Refunding every absence without checking the notice time against the meal cut-off rule.","Hiding a child's bump or scrape instead of logging the incident and informing parents."]},career:[{vi:"Giáo viên mầm non tập sự",en:"Trainee early childhood teacher"},{vi:"Giáo viên mầm non chủ nhiệm lớp",en:"Homeroom early childhood teacher"},{vi:"Tổ trưởng chuyên môn khối mẫu giáo",en:"Kindergarten curriculum team leader"},{vi:"Phó Hiệu trưởng, Hiệu trưởng trường mầm non",en:"Preschool Vice Principal, Principal"}],glossary:[{term:"Play-based learning",vi:"Học qua chơi: trẻ khám phá, trải nghiệm và hình thành kỹ năng thông qua hoạt động chơi có mục đích.",en:"An approach where children explore and build skills through purposeful play."},{term:"Daily routine",vi:"Chế độ sinh hoạt: khung thời gian hợp lý cho đón trẻ, học, chơi, ăn, ngủ, vệ sinh trong ngày.",en:"The structured daily schedule of arrival, learning, play, meals, naps and hygiene."},{term:"Growth chart",vi:"Biểu đồ tăng trưởng: cân nặng, chiều cao theo tuổi dựa trên chuẩn WHO để phát hiện suy dinh dưỡng, thừa cân.",en:"Weight and height-for-age charts based on WHO standards to detect undernutrition or overweight."},{term:"CMPA",vi:"Dị ứng đạm sữa bò ở trẻ nhỏ; phải loại bỏ sữa bò và chế phẩm khỏi khẩu phần theo chỉ định của bác sĩ.",en:"Cow's milk protein allergy; milk and dairy products must be removed from the diet as prescribed."},{term:"Meal count",vi:"Báo suất ăn: số suất giáo viên chốt với bếp mỗi sáng theo sĩ số thực tế và chế độ ăn đặc biệt.",en:"The number of meals the teacher confirms to the kitchen each morning from attendance and special diets."}],quiz:[{q:{vi:"Theo Điều lệ trường mầm non, lớp mẫu giáo 4-5 tuổi có tối đa bao nhiêu trẻ?",en:"Under the Preschool Charter, what is the maximum size of a 4-5 year-old class?"},options:{vi:["25 trẻ","30 trẻ","35 trẻ","40 trẻ"],en:["25 children","30 children","35 children","40 children"]},answer:1,explain:{vi:"Điều lệ quy định lớp 3-4 tuổi tối đa 25 trẻ, 4-5 tuổi tối đa 30 trẻ, 5-6 tuổi tối đa 35 trẻ.",en:"The Charter sets a maximum of 25 children for ages 3-4, 30 for ages 4-5 and 35 for ages 5-6."}},{q:{vi:"Bé nghỉ 4 ngày: 1 ngày báo trước 8:00, 3 ngày không báo; tiền ăn mô phỏng 30000 đồng/ngày, bếp chốt suất lúc 8:00. Tiền hoàn trả là bao nhiêu?",en:"A child misses 4 days: 1 notified before 8:00, 3 without notice; training meal fee 30000 VND/day, kitchen cut-off 8:00. What is the refund?"},options:{vi:["120000 đồng","90000 đồng","30000 đồng","0 đồng"],en:["120000 VND","90000 VND","30000 VND","0 VND"]},answer:2,explain:{vi:"Chỉ 1 ngày được báo trước giờ chốt suất: 1 x 30000 = 30000 đồng.",en:"Only 1 day was notified before the cut-off: 1 x 30000 = 30000 VND."}},{q:{vi:"Bếp hết sữa thay thế cho trẻ dị ứng đạm sữa bò, đồng nghiệp bảo cho uống sữa thường một bữa. Bạn làm gì?",en:"The kitchen has no substitute milk for a child with cow's milk allergy and a colleague suggests regular milk once. What do you do?"},options:{vi:["Cho uống ít một bữa","Để trẻ nhịn và không báo ai","Hỏi ý kiến các trẻ khác","Không cho dùng, đổi món an toàn, báo cấp trên và phụ huynh"],en:["Give a little just once","Let the child go without and tell no one","Ask the other children","Refuse, serve a safe substitute, inform the manager and parents"]},answer:3,explain:{vi:"Dị ứng có thể gây phản ứng nặng dù lượng nhỏ; an toàn của trẻ và sự minh bạch với gia đình là ưu tiên.",en:"Allergies can cause severe reactions even in small amounts; child safety and transparency with families come first."}},{q:{vi:"Phụ huynh nhờ cho trẻ uống thuốc ở trường. Giáo viên cần gì trước khi cho uống?",en:"A parent asks you to give a child medicine at school. What do you need first?"},options:{vi:["Phiếu gửi thuốc có chữ ký phụ huynh ghi rõ tên thuốc, liều, giờ uống","Chỉ cần lời dặn miệng","Tự điều chỉnh liều theo cân nặng của trẻ","Không cần gì nếu là thuốc bổ"],en:["A signed request stating the medicine, dose and time","A verbal instruction is enough","Adjust the dose yourself by the child's weight","Nothing if it is a vitamin"]},answer:0,explain:{vi:"Phải có yêu cầu bằng văn bản của phụ huynh và ghi sổ cho uống thuốc để bảo đảm đúng thuốc, đúng liều, đúng giờ.",en:"A written parent request and a medication log ensure the right medicine, dose and time."}}],tools_en:["Preschool management software","Electronic parent communication log","WHO standard growth charts","Play corner learning kits (STEAM, Montessori)","Child scales and height measuring boards","Classroom first aid kit"]}}})})(window.KKR);
